import io.agentscope.core.agent.*;import io.agentscope.core.event.*;import io.agentscope.core.message.*;import io.agentscope.core.model.*;import io.agentscope.core.permission.*;import io.agentscope.harness.agent.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;import reactor.core.publisher.*;
public class GChildErrorSourceProbe{public static void main(String[]a){AtomicInteger calls=new AtomicInteger();Model m=new Model(){public String getModelName(){return "no-network-source";}public Flux<ChatResponse> stream(List<Msg>msgs,List<ToolSchema>schemas,GenerateOptions opts){int n=calls.incrementAndGet();if(n==1)return Flux.just(ChatResponse.builder().id("root-first").usage(new ChatUsage(10,5,0)).content(List.of(ToolUseBlock.builder().id("spawn-call").name("agent_spawn").input(Map.of("agent_id","general-purpose","task","synthetic child task","timeout_seconds",5)).content("{\"agent_id\":\"general-purpose\",\"task\":\"synthetic child task\",\"timeout_seconds\":5}").build())).finishReason("tool_calls").build());if(n==2)return Flux.error(new IllegalStateException("synthetic child model failure"));boolean hasResult=msgs.stream().flatMap(x->x.getContent().stream()).anyMatch(x->x instanceof ToolResultBlock);String text=hasResult?"synthetic-parent-text":"synthetic-child-text";return Flux.just(ChatResponse.builder().id("response-"+n).usage(new ChatUsage(10,5,0)).content(List.of(TextBlock.builder().text(text).build())).finishReason("stop").build());}};var ag=HarnessAgent.builder().name("owned-parent-source").model(m).workspace(Path.of(a[0])).stateStore(new io.agentscope.core.state.InMemoryAgentStateStore()).permissionContext(PermissionContextState.builder().addAllowRule("agent_spawn",new PermissionRule("agent_spawn",null,PermissionBehavior.ALLOW,"synthetic approved task")).build()).build();try{var rc=RuntimeContext.builder().userId("synthetic-person").sessionId("owned-parent-session").build();var ev=ag.streamEvents(Msg.builder().role(MsgRole.USER).textContent("Synthetic parent request").build(),rc).collectList().block(java.time.Duration.ofSeconds(30));int rootText=0,childText=0;for(var e:ev){boolean child=e.getSource()!=null&&!e.getSource().isEmpty();System.out.println("EVENT="+e.getType()+" SOURCE="+(e.getSource()==null?"NULL":e.getSource()));if(e instanceof ToolResultEndEvent tr)System.out.println("TOOL_RESULT_STATE="+tr.getState());if(e instanceof TextBlockDeltaEvent t){if(child)childText+=t.getDelta().length();else rootText+=t.getDelta().length();System.out.println("TEXT_KIND="+(t.getDelta().contains("parent")?"PARENT":t.getDelta().contains("child")?"CHILD":"OTHER"));}}System.out.println("ROOT_TEXT_CHARS="+rootText);System.out.println("CHILD_TEXT_CHARS="+childText);System.out.println("MODEL_CALLS="+calls.get());}finally{ag.close();}}}
